#include <Python.h>
#include <numpy/arrayobject.h>
#include <float.h>
#include <string.h>
#include <stdlib.h>

typedef struct { double cost; int j; } Node;

static int cmp_node(const void *x, const void *y) {
    const Node *a = (const Node*)x, *b = (const Node*)y;
    if (a->cost < b->cost) return -1;
    if (a->cost > b->cost) return 1;
    return 0;
}

static PyObject* solve_lap(PyObject* self, PyObject* args) {
    PyArrayObject *Marr;
    if (!PyArg_ParseTuple(args, "O!", &PyArray_Type, &Marr)) return NULL;
    if (PyArray_NDIM(Marr) != 2) { PyErr_SetString(PyExc_ValueError, "need 2d"); return NULL; }
    int n = (int)PyArray_DIM(Marr, 0);
    int m = (int)PyArray_DIM(Marr, 1);
    if (n != m) { PyErr_SetString(PyExc_ValueError, "need square"); return NULL; }
    double *M = (double*)PyArray_DATA(Marr);

    npy_intp dims[1] = { n };
    PyArrayObject *ri = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_INT64);
    PyArrayObject *ci = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_INT64);
    long long *ri_d = (long long*)PyArray_DATA(ri);
    long long *ci_d = (long long*)PyArray_DATA(ci);

    double *u = (double*)malloc(n*sizeof(double));
    double *v = (double*)malloc(n*sizeof(double));
    double *p = (double*)malloc(n*sizeof(double));
    int *way = (int*)malloc(n*sizeof(int));
    int *match = (int*)malloc(n*sizeof(int));
    Node *nodes = (Node*)malloc(n*sizeof(Node));
    if (!u||!v||!p||!way||!match||!nodes) { PyErr_NoMemory(); return NULL; }

    for (int i=0;i<n;i++){ u[i]=0.0; v[i]=0.0; p[i]=0.0; way[i]=0; match[i]=-1; }

    for (int i=0;i<n;i++){
        for (int j=0;j<n;j++){ nodes[j].cost = M[i*n+j] - v[j]; nodes[j].j = j; }
        qsort(nodes, n, sizeof(Node), cmp_node);
        int j1 = nodes[0].j;
        double minv = nodes[0].cost;
        p[0] = (double)(i+1);
        for (int j=1;j<n;j++){
            double cost = nodes[j].cost;
            int jj = nodes[j].j;
            if (cost < minv) { minv = cost; j1 = jj; }
            p[j] = (double)(i+1);
        }
        u[i] = minv;
        for (int j=0;j<n;j++) v[j] += minv;
        int j0 = 0;
        int j = j1;
        int it = 0;
        do {
            int i1 = (int)p[j] - 1;
            double min = DBL_MAX;
            int j2 = -1;
            for (int jj=0;jj<n;jj++){
                if (p[jj] == 0.0) {
                    double cur = M[i1*n+jj] - u[i1] - v[jj];
                    if (cur < min) { min = cur; j2 = jj; }
                }
            }
            if (j2 < 0) break;
            v[j] += min;
            u[i1] += min;
            p[j] = (double)(i1+1);
            way[j] = j0;
            j0 = j;
            j = j2;
            it++;
            if (it > n+2) break;
        } while (j != j1);

        // augment
        int jj = j1;
        do {
            int jprev = way[jj];
            match[jj] = (int)p[jj] - 1;
            jj = jprev;
        } while (jj != 0);
    }

    for (int j=0;j<n;j++){
        int i = match[j];
        ri_d[i] = i;
        ci_d[i] = j;
    }

    free(u); free(v); free(p); free(way); free(match); free(nodes);
    return Py_BuildValue("(NN)", ri, ci);
}

static PyMethodDef methods[] = {
    {"solve_lap", solve_lap, METH_VARARGS, "solve lap"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "lapmod", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_lapmod(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
EOF
