#include <Python.h>
#include <numpy/arrayobject.h>
#include <float.h>
#include <stdlib.h>

static PyObject* solve_lap(PyObject* self, PyObject* args) {
    PyArrayObject *Marr;
    if (!PyArg_ParseTuple(args, "O!", &PyArray_Type, &Marr)) return NULL;
    if (PyArray_NDIM(Marr) != 2) { PyErr_SetString(PyExc_ValueError, "need 2d"); return NULL; }
    int n = (int)PyArray_DIM(Marr, 0);
    int m = (int)PyArray_DIM(Marr, 1);
    if (n != m) { PyErr_SetString(PyExc_ValueError, "need square"); return NULL; }
    double *M = (double*)PyArray_DATA(Marr);

    npy_intp dims[1] = { n };
    PyArrayObject *ri = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_INT64);
    PyArrayObject *ci = (PyArrayObject*)PyArray_SimpleNew(1, dims, NPY_INT64);
    long long *ri_d = (long long*)PyArray_DATA(ri);
    long long *ci_d = (long long*)PyArray_DATA(ci);

    int N = n;
    double *u = (double*)calloc(N+1, sizeof(double));
    double *v = (double*)calloc(N+1, sizeof(double));
    int *p = (int*)calloc(N+1, sizeof(int));
    int *way = (int*)calloc(N+1, sizeof(int));
    double *minv = (double*)malloc((N+1)*sizeof(double));
    char *used = (char*)malloc((N+1)*sizeof(char));
    if (!u||!v||!p||!way||!minv||!used) { PyErr_NoMemory(); return NULL; }

    for (int i=1; i<=N; i++) {
        p[0] = i;
        int j0 = 0;
        for (int j=0; j<=N; j++) { minv[j] = DBL_MAX; used[j] = 0; }
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = DBL_MAX;
            int j1 = -1;
            double *row = M + (i0-1)*N;
            for (int j=1; j<=N; j++) {
                if (!used[j]) {
                    double cur = row[j-1] - u[i0] - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (int j=0; j<=N; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else { minv[j] -= delta; }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0 != 0);
    }

    for (int j=1; j<=N; j++) {
        int i = p[j];
        ri_d[i-1] = i-1;
        ci_d[i-1] = j-1;
    }

    free(u); free(v); free(p); free(way); free(minv); free(used);
    return Py_BuildValue("(NN)", ri, ci);
}

