// auction algorithm for min-cost assignment
// cost: n x n row-major
// returns assignment x[i] = column for row i
// uses epsilon scaling

void auction(int n, double *cost, int *x, double eps_final) {
    double *p = calloc(n, sizeof(double));  // prices
    int *owner = malloc(n * sizeof(int));   // owner[j] = row assigned to col j
    for (int j = 0; j < n; j++) owner[j] = -1;

    double eps = 1.0;  // start
    // actually start with max cost
    double maxc = 0;
    for (int i = 0; i < n*n; i++) if (cost[i] > maxc) maxc = cost[i];
    eps = maxc;

    int num_unassigned = n;
    int *unassigned = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) unassigned[i] = i;

    while (eps > eps_final) {
        // bidding phase
        int new_num = 0;
        for (int k = 0; k < num_unassigned; k++) {
            int i = unassigned[k];
            // find best and second best
            double best = -1e300, second = -1e300;
            int bestj = -1;
            for (int j = 0; j < n; j++) {
                double val = -cost[i*n+j] - p[j];
                if (val > best) { second = best; best = val; bestj = j; }
                else if (val > second) second = val;
            }
            double bid = best - second + eps;
            p[bestj] += bid;
            int prev = owner[bestj];
            owner[bestj] = i;
            if (prev != -1) unassigned[new_num++] = prev;
        }
        num_unassigned = new_num;
        if (num_unassigned == 0) {
            eps *= 0.25;  // reduce epsilon
            // all rows assigned; but we need to re-unassign? No.
            // Actually, when epsilon reduces, the current assignment might not be optimal,
            // so we need to re-run bidding. But all rows are assigned.
            // Standard approach: after epsilon reduction, unassign all rows and re-bid.
            // Or: keep assignment and continue bidding (but no unassigned rows).
            // The standard forward auction: after epsilon reduction, all rows become unassigned again.
            for (int i = 0; i < n; i++) unassigned[i] = i;
            num_unassigned = n;
            // but keep prices and owner? Actually reset owner.
            for (int j = 0; j < n; j++) owner[j] = -1;
        }
    }
    // final assignment
    for (int j = 0; j < n; j++) x[owner[j]] = j;
}
