                if (v < best) { second = best; best = v; jbest = j; }
                else if (v < second) second = v;
            }
            double bid = (second - best) + eps;
            price[jbest] += bid;
            int prev = assigned[jbest];
            assigned[jbest] = i;
            if (prev != -1) unassigned[top++] = prev;
        }
        eps /= 2.0;
    }

    for (int j = 0; j < n; j++) {
        int i = assigned[j];
        ri_d[i] = i;
        ci_d[i] = j;
    }

    free(price); free(assigned); free(unassigned);
    return Py_BuildValue("(NN)", ri, ci);
}

static PyMethodDef methods[] = {
    {"solve_lap", solve_lap, METH_VARARGS, "solve lap"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "lapmod", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_lapmod(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
